package dev.pocketengine.features.plugins;

import static org.junit.Assert.*;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;

/** Declaration-only transport separation; none of these data functions admits a process. */
public final class McpStdioDataTest {
    private static final String CONFIG="a".repeat(64),SERVER="b".repeat(64);
    private static JSONObject remote()throws Exception{return new JSONObject().put("name","write_note").put("description","Untrusted note writer").put("inputSchema",new JSONObject().put("type","object").put("properties",new JSONObject().put("text",new JSONObject().put("type","string"))).put("required",new JSONArray().put("text")).put("additionalProperties",false));}
    private static JSONObject declaration()throws Exception{return McpStdioData.declaration(remote(),CONFIG,McpStdioClient.VERSION,SERVER);}
    private static JSONObject normalized(JSONObject tool)throws Exception{return PluginRules.manifest(new JSONObject().put("id","local").put("name","Local").put("version","v1").put("tools",new JSONArray().put(tool))).getJSONArray("tools").getJSONObject(0);}
    @Test public void stdioKeepsOriginalMcpKindButPinsItsExplicitTransportConfigurationAndDescriptor()throws Exception{JSONObject tool=declaration();assertEquals("mcp",tool.getString("kind"));assertEquals("stdio",tool.getString("transport"));assertEquals("write",tool.getString("effect"));assertEquals(CONFIG,tool.getString("configurationDigest"));assertEquals(SERVER,tool.getString("serverDigest"));assertEquals(dev.pocketengine.features.plugins.mcp.McpJson.digest(remote()),tool.getString("descriptorDigest"));assertFalse(tool.has("endpoint"));assertFalse(tool.has("argv"));assertFalse(tool.has("executionAuthorized"));assertEquals(McpData.digest(tool),McpData.digest(normalized(tool)));}
    @Test public void oldImplicitHttpDeclarationRemainsByteForByteCanonicalCompatible()throws Exception{JSONObject tool=McpData.declaration(remote(),"https://example.invalid/mcp",McpData.VERSION,SERVER);assertFalse(tool.has("transport"));assertFalse(tool.has("configurationDigest"));assertEquals(McpData.digest(tool),McpData.digest(normalized(tool)));assertEquals("https://example.invalid/mcp",tool.getString("endpoint"));}
    @Test public void explicitHttpTransportStillUsesTheOriginalEndpointPolicy()throws Exception{JSONObject tool=McpData.declaration(remote(),"https://example.invalid/mcp",McpData.LEGACY,SERVER).put("transport","streamable_http");assertEquals("streamable_http",normalized(tool).getString("transport"));assertThrows(IllegalArgumentException.class,()->normalized(new JSONObject(tool.toString()).put("endpoint","file:///tmp/server.py")));}
    @Test public void unknownNullOrNonStringTransportNeverFallsBackToHttp()throws Exception{JSONObject tool=McpData.declaration(remote(),"https://example.invalid/mcp",McpData.VERSION,SERVER);for(Object transport:new Object[]{"pipe","pty","stdio_http",42,JSONObject.NULL})assertThrows(String.valueOf(transport),IllegalArgumentException.class,()->normalized(new JSONObject(tool.toString()).put("transport",transport)));}
    @Test public void stdioCannotBorrowAnHttpEndpointOrNewerHttpProtocolVersion()throws Exception{JSONObject tool=declaration();assertThrows(IllegalArgumentException.class,()->normalized(new JSONObject(tool.toString()).put("endpoint","https://example.invalid/mcp")));assertThrows(IllegalArgumentException.class,()->normalized(new JSONObject(tool.toString()).put("protocolVersion",McpData.VERSION)));}
    @Test public void configurationReferenceIsMandatoryAndExactNotACoercedOrEmptyValue()throws Exception{JSONObject tool=declaration();JSONObject missing=new JSONObject(tool.toString());missing.remove("configurationDigest");assertThrows(IllegalArgumentException.class,()->normalized(missing));for(Object value:new Object[]{"", "x".repeat(64),42,JSONObject.NULL})assertThrows(IllegalArgumentException.class,()->normalized(new JSONObject(tool.toString()).put("configurationDigest",value)));}
    @Test public void httpHeaderAnnotationsDoNotTurnIntoAnUnimplementedStdioCredentialChannel()throws Exception{JSONObject remote=remote();remote.getJSONObject("inputSchema").getJSONObject("properties").getJSONObject("text").put("x-mcp-header","X-Private");JSONObject preview=McpStdioData.previewTool(remote,CONFIG,McpStdioClient.VERSION,SERVER);assertFalse(preview.getBoolean("supported"));assertTrue(preview.getString("unsupportedReason").contains("header"));assertFalse(preview.has("declaration"));}
    @Test public void unsupportedTasksAndSchemaRemainExplicitlyUnsupportedNotSilentlyRewritten()throws Exception{JSONObject remote=remote();remote.put("execution",new JSONObject().put("taskSupport","required"));assertFalse(McpStdioData.previewTool(remote,CONFIG,McpStdioClient.VERSION,SERVER).getBoolean("supported"));remote=remote();remote.getJSONObject("inputSchema").put("oneOf",new JSONArray());assertFalse(McpStdioData.previewTool(remote,CONFIG,McpStdioClient.VERSION,SERVER).getBoolean("supported"));}
    @Test public void selectingOnlyOriginalDiscoveredNamesRemainsBoundedAndDuplicateFree()throws Exception{JSONArray definitions=new JSONArray().put(remote());JSONObject manifest=McpStdioData.manifest("local","Local",CONFIG,McpStdioClient.VERSION,SERVER,definitions,new JSONArray().put("write_note"));assertEquals(1,manifest.getJSONArray("tools").length());for(JSONArray selection:new JSONArray[]{new JSONArray(),new JSONArray().put("missing"),new JSONArray().put("write_note").put("write_note")})assertThrows(IllegalArgumentException.class,()->McpStdioData.manifest("local","Local",CONFIG,McpStdioClient.VERSION,SERVER,definitions,selection));JSONArray oversized=new JSONArray();for(int i=0;i<13;i++)oversized.put("write_note");assertThrows(IllegalArgumentException.class,()->McpStdioData.manifest("local","Local",CONFIG,McpStdioClient.VERSION,SERVER,definitions,oversized));}
    @Test public void changingSourceConfigurationChangesManifestIdentityAndRevisionDiffWithoutChangingRemoteNames()throws Exception{JSONArray definitions=new JSONArray().put(remote()),selection=new JSONArray().put("write_note");JSONObject before=McpStdioData.manifest("local","Local",CONFIG,McpStdioClient.VERSION,SERVER,definitions,selection),after=McpStdioData.manifest("local","Local","c".repeat(64),McpStdioClient.VERSION,SERVER,definitions,selection);assertNotEquals(before.getString("version"),after.getString("version"));JSONObject current=new JSONObject().put("id","local").put("installationId",java.util.UUID.randomUUID().toString()).put("stateRevision",0).put("manifest",before);JSONArray fields=PluginRevisions.preview(current,after).getJSONArray("changedTools").getJSONObject(0).getJSONArray("fields");assertTrue(fields.toString().contains("configurationDigest"));assertEquals("write_note",after.getJSONArray("tools").getJSONObject(0).getString("name"));}
    @Test public void projectionDoesNotAliasTheUntrustedRemoteSchema()throws Exception{JSONObject remote=remote(),tool=McpStdioData.declaration(remote,CONFIG,McpStdioClient.VERSION,SERVER);String digest=McpData.digest(tool);remote.getJSONObject("inputSchema").getJSONObject("properties").getJSONObject("text").put("type","number");assertEquals(digest,McpData.digest(tool));assertNotEquals(dev.pocketengine.features.plugins.mcp.McpJson.digest(remote),tool.getString("descriptorDigest"));}
}
